package com.knowflow.learning.adaptive;
import com.fasterxml.jackson.databind.*;import com.knowflow.exception.BusinessException;import com.knowflow.learning.actions.LearningWriteGuard;import com.knowflow.learning.evidence.LearningEvidenceSources;import com.knowflow.learning.feedback.*;import com.knowflow.mapper.*;import com.knowflow.entity.*;import com.knowflow.service.*;import com.knowflow.vo.*;import lombok.RequiredArgsConstructor;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import jakarta.validation.constraints.*;import java.util.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
/** Per-user study suggestions over original paths. Does not change canonical paths, grades or the NextAction resolver. */
@Service @RequiredArgsConstructor @ConditionalOnProperty(name={"knowflow.product.adaptive-learning.enabled","knowflow.product.interview-learning.enabled","knowflow.product.private-quiz.enabled","knowflow.product.tutor.enabled","knowflow.product.tutor-coaching.enabled"},havingValue="true")
public class AdaptivePathService {
 private final JdbcTemplate sql;private final ObjectMapper json;private final LearningService learning;private final LearningPathMapper paths;private final KgEntityMapper knowledge;private final ResourceKnowledgeMappingMapper mappings;private final KnowledgeMasteryService mastery;private final LearningEvidenceSources scope;private final ErrorAnnotationService errors;private final FeedbackSourceService sources;private final GraphInsightService graph;private final LearningWriteGuard guard;private final com.knowflow.security.DocumentAccessPolicy access;private final DocDocumentMapper docs;private final LearningChapterMapper chapterMapper;private final com.knowflow.mapper.TaskMapper taskMapper;private final NoteService notes;private final com.knowflow.learning.actions.LearningContextService resourceAccess;private final AdaptivePathOrder personalOrder;
 public record Preview(@NotNull @Min(0)Long expectedRevision,@NotBlank @Pattern(regexp="[A-Za-z0-9_-]{8,80}")String requestId,@NotNull @Size(max=200)List<@NotNull @Positive Long> lockedChapterIds){}
 public record Decision(@NotNull @Min(0)Long expectedRevision,@NotBlank @Pattern(regexp="[A-Za-z0-9_-]{8,80}")String requestId,@NotBlank @Size(max=100)String key){}
 private long n(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}
 private String write(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalStateException(e);}}
 private JsonNode read(Object x){try{return json.readTree(x.toString());}catch(Exception e){throw new IllegalStateException("路径建议记录损坏");}}
 private String sha(Object x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.copy().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsBytes(x)));}catch(Exception e){throw new IllegalStateException(e);}}
 private List<Long> ids(String raw){if(raw==null||raw.isBlank())return List.of();var ids=new ArrayList<Long>();for(String v:raw.split(","))try{long id=Long.parseLong(v.trim());if(id<1)throw new NumberFormatException();ids.add(id);}catch(NumberFormatException e){throw new BusinessException(409,"章节关联或前置ID无效，请先核对原路径");}return ids;}
 private List<LearningChapterVO> chapters(long user,long path){learning.getPathDetail(path,user);var original=paths.selectById(path);if(original.getOwnerUserId()!=null&&original.getOwnerUserId()!=0&&original.getOwnerUserId()!=user)throw new BusinessException(403,"不能调整他人的私人路径");var rows=learning.getChapterList(path,user);if(rows.size()>200)throw new BusinessException(409,"首批仅支持200章以内路径");var map=new LinkedHashMap<Long,LearningChapterVO>();rows.forEach(ch->map.put(ch.getId(),ch));Set<Long> seen=new HashSet<>(),visiting=new HashSet<>();for(long id:map.keySet())visit(id,map,seen,visiting);return rows;}
 private void visit(long id,Map<Long,LearningChapterVO> chapters,Set<Long> seen,Set<Long> visiting){if(seen.contains(id))return;if(!chapters.containsKey(id)||!visiting.add(id))throw new BusinessException(409,"原路径存在循环或跨路径前置依赖，未生成建议");for(long p:ids(chapters.get(id).getPrerequisiteChapterIds()))visit(p,chapters,seen,visiting);visiting.remove(id);seen.add(id);}
 private Map<String,Object> state(long user,long path){var rows=sql.queryForList("SELECT * FROM adaptive_path_state WHERE owner_id=? AND path_id=?",user,path);return rows.isEmpty()?Map.of("revision",0L,"locks_json","[]","deferred_json","[]"):rows.get(0);}
 private void ensure(long user,long path){if(sql.queryForObject("SELECT COUNT(*) FROM adaptive_path_state WHERE owner_id=? AND path_id=?",Integer.class,user,path)==0)sql.update("INSERT INTO adaptive_path_state(owner_id,path_id,revision,locks_json,deferred_json,updated_at) VALUES(?,?,0,'[]','[]',CURRENT_TIMESTAMP)",user,path);}
 private Set<Long> longs(Object value){var result=new HashSet<Long>();read(value).forEach(v->result.add(v.asLong()));return result;}
 private Set<String> strings(Object value){var result=new HashSet<String>();read(value).forEach(v->result.add(v.asText()));return result;}
 private boolean readable(LearningChapterVO ch,long user){for(long doc:ids(ch.getDocIds()))if(!access.canRead(docs.selectById(doc),user))return false;return true;}
 private List<KgEntity> pathKnowledge(List<LearningChapterVO> chapters,long user){Set<Long> documents=new HashSet<>();chapters.stream().filter(ch->readable(ch,user)).forEach(ch->documents.addAll(ids(ch.getDocIds())));if(documents.isEmpty())return List.of();var all=knowledge.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<KgEntity>().in(KgEntity::getDocId,documents).orderByAsc(KgEntity::getId));var result=new ArrayList<KgEntity>();for(var k:all)try{scope.requireKnowledge(k.getId(),user);result.add(k);}catch(BusinessException e){if(!Set.of(403,404).contains(e.getCode()))throw e;}return result;}
 public List<Map<String,Object>> facts(long user,long path){var chapters=chapters(user,path);var current=state(user,path);var deferred=strings(current.get("deferred_json"));var nodes=pathKnowledge(chapters,user);var byId=new LinkedHashMap<Long,KgEntity>();nodes.forEach(k->byId.put(k.getId(),k));var candidates=new LinkedHashMap<String,Map<String,Object>>();
  for(long annotation:sql.queryForList("SELECT id FROM learning_error_annotation WHERE owner_id=? AND state='SUCCEEDED' ORDER BY id DESC LIMIT 100",Long.class,user)){
   try{var diagnosis=errors.detail(annotation,user);var ks=mappings.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<ResourceKnowledgeMapping>().eq(ResourceKnowledgeMapping::getResourceType,"ERROR_ANNOTATION").eq(ResourceKnowledgeMapping::getResourceId,annotation).eq(ResourceKnowledgeMapping::getStatus,"ACCEPTED").eq(ResourceKnowledgeMapping::getSource,"MANUAL"));
    for(var link:ks){var k=byId.get(link.getKnowledgeId());if(k==null)continue;var source=sources.read(user,diagnosis.get("sourceType").toString(),((Number)diagnosis.get("sourceId")).longValue(),((Number)diagnosis.get("questionIndex")).intValue());var refs=new ArrayList<Map<String,Object>>();refs.add(Map.of("type","ERROR_ANNOTATION","id",annotation));String reason="已有错因建议 #"+annotation+"，先核对该知识点；AI分类不证明真实认知原因";
     if("INTERVIEW_TURN".equals(source.type())){for(var plan:sql.queryForList("SELECT retest_turn FROM learning_interview_retest WHERE owner_id=? AND baseline_turn=? AND retest_turn IS NOT NULL",user,source.id())){var retest=sources.read(user,"INTERVIEW_TURN",n(plan,"retest_turn"),0);var score=retest.evaluation().path("radarGrade").path("score");if(score.isNumber()&&score.asDouble()<8.5){reason+="；原题复测AI参考分 "+score.asDouble()+"/10，低于8.5参考线（不是客观掌握）";refs.add(Map.of("type","INTERVIEW_TURN","id",retest.id()));}}}
     var item=item(k,chapters,user,reason,refs,source.noteId());var practice=errors.practice(annotation,user);reason+="；已关联真实微挑战交卷 "+practice.get("completedCount")+" 次（不等于掌握）";item.put("reason",reason);item.put("annotationId",annotation);candidates.putIfAbsent(item.get("key").toString(),item);
    }
   }catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;}
  }
  for(var k:nodes){var m=mastery.getDetail(user,k.getId());if(!Set.of("WEAK","REVIEW_REQUIRED").contains(m.getLearningStatus()))continue;var item=item(k,chapters,user,"原掌握度状态："+m.getLearningStatus()+"；"+Objects.toString(m.getReason(),"证据有限"),List.of(Map.of("type","KNOWLEDGE_MASTERY","id",k.getId())),null);candidates.putIfAbsent(item.get("key").toString(),item);}
  for(var task:sql.queryForList("SELECT id,title,learning_metadata FROM task WHERE user_id=? AND deleted=0 AND status=0 AND scheduled_date<=CURRENT_DATE ORDER BY scheduled_date,id LIMIT 50",user)){if(task.get("learning_metadata")==null)continue;var meta=read(task.get("learning_metadata"));var k=byId.get(meta.path("knowledgeId").asLong());if(k==null)continue;var item=item(k,chapters,user,"到期未完成任务："+task.get("title"),List.of(Map.of("type","TASK","id",n(task,"id"))),null);candidates.putIfAbsent(item.get("key").toString(),item);}
  var out=new ArrayList<Map<String,Object>>();for(var item:candidates.values())if(!deferred.contains(item.get("key"))&&item.get("chapterId")!=null)out.add(item);
  for(var ch:chapters)if(out.size()<3&&!Boolean.TRUE.equals(ch.getCompleted())&&!Boolean.TRUE.equals(ch.getLocked())&&readable(ch,user)&&!deferred.contains("chapter:"+ch.getId())&&out.stream().noneMatch(i->Objects.equals(i.get("chapterId"),ch.getId()))){var item=new LinkedHashMap<String,Object>();item.put("key","chapter:"+ch.getId());item.put("chapterId",ch.getId());item.put("title",ch.getTitle());item.put("reason","原路径顺序中的可学习章节；无充分证据时采用明确冷启动，不推断薄弱");item.put("method","阅读与复述");item.put("sourceRefs",List.of(Map.of("type","CHAPTER","id",ch.getId())));out.add(item);}
  return out.stream().limit(3).toList();
 }
 private Map<String,Object> item(KgEntity k,List<LearningChapterVO> chapters,long user,String reason,List<Map<String,Object>> refs,Long note){var item=new LinkedHashMap<String,Object>();item.put("key","knowledge:"+k.getId());item.put("knowledgeId",k.getId());item.put("title",k.getName());item.put("chapterId",chapters.stream().filter(ch->!Boolean.TRUE.equals(ch.getCompleted())&&!Boolean.TRUE.equals(ch.getLocked())&&readable(ch,user)&&ids(ch.getDocIds()).contains(k.getDocId())).map(LearningChapterVO::getId).findFirst().orElse(null));item.put("reason",reason);item.put("method","针对已有依据补练或复述");item.put("sourceRefs",refs);if(note==null){var insight=graph.detail(user,k.getId());var notes=(List<Map<String,Object>>)insight.get("practiceNotes");if(!notes.isEmpty())note=n(notes.get(0),"id");}item.put("noteId",note);return item;}
 @Transactional public Map<String,Object> bind(long user,long path,long annotation,long kid){guard.lock(user);var chapters=chapters(user,path);errors.detail(annotation,user);if(pathKnowledge(chapters,user).stream().noneMatch(k->k.getId()==kid))throw new BusinessException(403,"知识点不属于当前可读路径来源");var existing=mappings.selectList(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<ResourceKnowledgeMapping>().eq(ResourceKnowledgeMapping::getResourceType,"ERROR_ANNOTATION").eq(ResourceKnowledgeMapping::getResourceId,annotation).eq(ResourceKnowledgeMapping::getKnowledgeId,kid));if(existing.isEmpty()){if(sql.queryForObject("SELECT COUNT(*) FROM resource_knowledge_mapping WHERE resource_type='ERROR_ANNOTATION' AND resource_id=? AND knowledge_id=?",Integer.class,annotation,kid)>0)throw new BusinessException(409,"映射曾被删除，需人工核对，未自动恢复");var m=new ResourceKnowledgeMapping();m.setResourceType("ERROR_ANNOTATION");m.setResourceId(annotation);m.setKnowledgeId(kid);m.setSource("MANUAL");m.setStatus("ACCEPTED");m.setConfidence(java.math.BigDecimal.ONE);mappings.insert(m);}else if(!"ACCEPTED".equals(existing.get(0).getStatus())||!"MANUAL".equals(existing.get(0).getSource()))throw new BusinessException(409,"已有不同映射，请先核对，未自动覆盖");return Map.of("annotationId",annotation,"knowledgeId",kid,"notice","只保存明确知识身份，不改变成绩或掌握度");}
 public Map<String,Object> detail(long user,long path){var chapters=chapters(user,path);var s=state(user,path);var out=new LinkedHashMap<String,Object>();out.put("pathId",path);out.put("revision",s.get("revision"));out.put("effectiveOrder",chapters.stream().map(LearningChapterVO::getId).toList());out.put("personalOrderStale",s.get("order_hash")!=null&&!s.get("order_hash").equals(personalOrder.canonicalHash(path)));out.put("lockedChapterIds",read(s.get("locks_json")));out.put("deferredKeys",read(s.get("deferred_json")));out.put("suggestions",facts(user,path));out.put("knowledgeNodes",pathKnowledge(chapters,user).stream().map(k->Map.of("id",k.getId(),"name",k.getName())).toList());var annotations=new ArrayList<Map<String,Object>>();for(long annotation:sql.queryForList("SELECT id FROM learning_error_annotation WHERE owner_id=? AND state='SUCCEEDED' ORDER BY id DESC LIMIT 50",Long.class,user)){try{var a=errors.detail(annotation,user);var source=sources.read(user,a.get("sourceType").toString(),((Number)a.get("sourceId")).longValue(),((Number)a.get("questionIndex")).intValue());annotations.add(Map.of("id",annotation,"question",source.question()));}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;}}out.put("annotations",annotations);out.put("chapters",chapters.stream().map(ch->Map.of("id",ch.getId(),"title",ch.getTitle(),"completed",Boolean.TRUE.equals(ch.getCompleted()),"locked",Boolean.TRUE.equals(ch.getLocked()))).toList());var history=new ArrayList<Map<String,Object>>();for(var r:sql.queryForList("SELECT * FROM adaptive_path_revision WHERE owner_id=? AND path_id=? ORDER BY id DESC LIMIT 30",user,path)){var row=new LinkedHashMap<String,Object>();row.put("id",r.get("id"));row.put("state",r.get("state"));row.put("baseRevision",r.get("base_revision"));row.put("createdAt",r.get("created_at"));if(visible(read(r.get("payload")),user,n(r,"path_id")))row.put("payload",read(r.get("payload")));else row.put("sourceUnavailable",true);history.add(row);}out.put("history",history);return out;}
 private String pathHash(List<LearningChapterVO> chapters){return sha(chapters.stream().map(ch->Arrays.asList(ch.getId(),ch.getSortOrder(),ch.getPrerequisiteChapterIds(),ch.getDocIds(),ch.getCompleted(),ch.getContentHash())).toList());}
 private List<Long> order(List<LearningChapterVO> chapters,Set<Long> locks,List<Map<String,Object>> suggestions){Map<Long,Integer> targets=new HashMap<>();for(int rank=0;rank<suggestions.size();rank++){var s=suggestions.get(rank);if(s.get("chapterId") instanceof Number n)targets.putIfAbsent(n.longValue(),rank);}var map=new LinkedHashMap<Long,LearningChapterVO>();chapters.forEach(ch->map.put(ch.getId(),ch));if(!map.keySet().containsAll(locks))throw new BusinessException(400,"锁定章节不属于当前路径");Set<Long> done=new HashSet<>();chapters.stream().filter(ch->Boolean.TRUE.equals(ch.getCompleted())).forEach(ch->done.add(ch.getId()));Set<Long> fixed=new HashSet<>(locks);fixed.addAll(done);var result=new ArrayList<Long>();for(int i=0;i<chapters.size();i++){var at=chapters.get(i);if(fixed.contains(at.getId())){if(!done.contains(at.getId())&&!ids(at.getPrerequisiteChapterIds()).stream().allMatch(p->done.contains(p)||result.contains(p)))throw new BusinessException(409,"锁定位置与前置条件冲突，未移动锁定章节");result.add(at.getId());continue;}var available=chapters.stream().filter(ch->!fixed.contains(ch.getId())&&!result.contains(ch.getId())&&ids(ch.getPrerequisiteChapterIds()).stream().allMatch(p->done.contains(p)||result.contains(p))).sorted(Comparator.comparingInt(ch->targets.getOrDefault(ch.getId(),Integer.MAX_VALUE))).findFirst().orElseThrow(()->new BusinessException(409,"前置条件与锁定约束没有可行顺序"));result.add(available.getId());}return result;}
 @Transactional public Map<String,Object> preview(long user,long path,Preview input){guard.lock(user);var chapters=chapters(user,path);ensure(user,path);var s=state(user,path);var locks=new TreeSet<>(input.lockedChapterIds());String hash=sha(Arrays.asList(path,input.expectedRevision(),locks));var old=sql.queryForList("SELECT * FROM adaptive_path_revision WHERE owner_id=? AND request_id=?",user,input.requestId());if(!old.isEmpty()){var r=old.get(0);if(n(r,"path_id")!=path||!hash.equals(r.get("input_hash")))throw new BusinessException(409,"预览标识已用于其他参数");return revision(r,user);}if(n(s,"revision")!=input.expectedRevision())throw new BusinessException(409,"建议版本已更新，请重新读取");var facts=facts(user,path);var payload=Map.of("originalOrder",chapters.stream().map(LearningChapterVO::getId).toList(),"proposedOrder",order(chapters,locks,facts),"lockedChapterIds",locks,"suggestions",facts,"pathHash",pathHash(chapters),"factsHash",sha(facts));sql.update("INSERT INTO adaptive_path_revision(owner_id,path_id,base_revision,request_id,input_hash,payload,state,created_at) VALUES(?,?,?,?,?,?,'PREVIEW',CURRENT_TIMESTAMP)",user,path,input.expectedRevision(),input.requestId(),hash,write(payload));return revision(sql.queryForMap("SELECT * FROM adaptive_path_revision WHERE owner_id=? AND request_id=?",user,input.requestId()),user);}
 private boolean visible(JsonNode payload,long user,long path){try{for(var s:payload.path("suggestions")){
 if(s.path("chapterId").isIntegralNumber()){var ch=chapterMapper.selectById(s.path("chapterId").asLong());if(ch==null||ch.getPathId()!=path)return false;learning.getPathDetail(ch.getPathId(),user);for(long doc:ids(ch.getDocIds()))if(!access.canRead(docs.selectById(doc),user))return false;}
 if(s.path("noteId").isIntegralNumber()){var note=notes.detail(s.path("noteId").asLong(),user,false);if(note.getSourceDocId()!=null)access.requireRead(docs.selectById(note.getSourceDocId()),user);}
 for(var ref:s.path("sourceRefs"))if("TASK".equals(ref.path("type").asText())){var task=taskMapper.selectById(ref.path("id").asLong());if(task==null||!Objects.equals(task.getUserId(),user))return false;if(task.getLearningMetadata()!=null){var meta=read(task.getLearningMetadata());String type=meta.path("resourceType").asText();Long resource=meta.path("resourceId").isIntegralNumber()?meta.path("resourceId").asLong():null;resourceAccess.validateResource(new com.knowflow.learning.actions.PlanModels.Item("check","source","REVIEW",1,"P1",type,resource,null,null,"source check","none",task.getId(),"TASK",task.getStatus()),user);}}
if(s.path("knowledgeId").isIntegralNumber())scope.requireKnowledge(s.path("knowledgeId").asLong(),user);if(s.path("annotationId").isIntegralNumber())errors.detail(s.path("annotationId").asLong(),user);}return true;}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;return false;}}
 private Map<String,Object> revision(Map<String,Object> r,long user){if(!visible(read(r.get("payload")),user,n(r,"path_id")))return Map.of("id",r.get("id"),"state",r.get("state"),"baseRevision",r.get("base_revision"),"sourceUnavailable",true);return Map.of("id",r.get("id"),"state",r.get("state"),"baseRevision",r.get("base_revision"),"payload",read(r.get("payload")));}
 @Transactional public Map<String,Object> confirm(long user,long path,long revision,boolean accept){guard.lock(user);var chapters=chapters(user,path);var rows=sql.queryForList("SELECT * FROM adaptive_path_revision WHERE id=? AND owner_id=? AND path_id=?",revision,user,path);if(rows.isEmpty())throw new BusinessException(404,"建议版本不存在");var r=rows.get(0);if(!"PREVIEW".equals(r.get("state"))){if((accept?"APPLIED":"REJECTED").equals(r.get("state")))return revision(r,user);throw new BusinessException(409,"建议已有不同决定");}var s=state(user,path);if(n(s,"revision")!=n(r,"base_revision"))throw new BusinessException(409,"建议版本冲突，请重新预览");var p=read(r.get("payload"));if(!p.path("pathHash").asText().equals(pathHash(chapters))||!p.path("factsHash").asText().equals(sha(facts(user,path))))throw new BusinessException(409,"原路径或学习来源已变化，请重新预览");if(accept){sql.update("UPDATE adaptive_path_state SET revision=revision+1,locks_json=?,order_json=?,order_hash=?,updated_at=CURRENT_TIMESTAMP WHERE owner_id=? AND path_id=?",p.path("lockedChapterIds").toString(),p.path("proposedOrder").toString(),personalOrder.canonicalHash(path),user,path);}sql.update("UPDATE adaptive_path_revision SET state=?,applied_at=CURRENT_TIMESTAMP WHERE id=?",accept?"APPLIED":"REJECTED",revision);return revision(sql.queryForMap("SELECT * FROM adaptive_path_revision WHERE id=?",revision),user);}
 @Transactional public Map<String,Object> defer(long user,long path,Decision input){guard.lock(user);chapters(user,path);ensure(user,path);var old=sql.queryForList("SELECT * FROM adaptive_path_revision WHERE owner_id=? AND request_id=?",user,input.requestId());String hash=sha(Arrays.asList(path,input.expectedRevision(),input.key()));if(!old.isEmpty()){if(!hash.equals(old.get(0).get("input_hash")))throw new BusinessException(409,"决定标识冲突");return detail(user,path);}var s=state(user,path);if(n(s,"revision")!=input.expectedRevision())throw new BusinessException(409,"建议版本冲突");if(facts(user,path).stream().noneMatch(f->input.key().equals(f.get("key"))))throw new BusinessException(409,"该建议已变化");var keys=new TreeSet<>(strings(s.get("deferred_json")));keys.add(input.key());sql.update("UPDATE adaptive_path_state SET revision=revision+1,deferred_json=?,updated_at=CURRENT_TIMESTAMP WHERE owner_id=? AND path_id=?",write(keys),user,path);sql.update("INSERT INTO adaptive_path_revision(owner_id,path_id,base_revision,request_id,input_hash,payload,state,created_at) VALUES(?,?,?,?,?,?,'DEFERRED',CURRENT_TIMESTAMP)",user,path,input.expectedRevision(),input.requestId(),hash,write(Map.of("deferredKey",input.key())));return detail(user,path);}
}
